:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --primary: #e94560;
  --text: #eaeaea;
  --accent: #0f3460;
  --focus: #f5c542;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  background-color: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  background-image: repeating-linear-gradient(
    0deg,
    transparent,
    transparent 2px,
    rgba(255,255,255,0.03) 2px,
    rgba(255,255,255,0.03) 4px
  );
}

.card {
  background-color: var(--card-bg);
  padding: 32px 24px;
  border: 4px solid var(--primary);
  box-shadow: 8px 8px 0 rgba(0,0,0,0.4);
  text-align: center;
  width: 100%;
  max-width: 400px;
  image-rendering: pixelated;
}

h1 {
  font-size: 1.5rem;
  letter-spacing: 2px;
  text-transform: uppercase;
  margin-bottom: 16px;
  color: var(--primary);
  text-shadow: 2px 2px 0 #000;
}

.mode-indicator {
  font-size: 1.125rem;
  font-weight: bold;
  letter-spacing: 1px;
  text-transform: uppercase;
  margin-bottom: 8px;
  padding: 4px 8px;
  background-color: var(--accent);
  display: inline-block;
  border: 2px solid var(--text);
}

.timer-display {
  font-size: 4rem;
  font-weight: bold;
  font-variant-numeric: tabular-nums;
  letter-spacing: 4px;
  margin: 16px 0 24px;
  color: var(--text);
  text-shadow: 4px 4px 0 #000;
  line-height: 1.2;
}

.controls {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

button {
  font-family: inherit;
  font-size: 1.125rem;
  font-weight: bold;
  text-transform: uppercase;
  letter-spacing: 1px;
  padding: 12px 24px;
  border: 3px solid var(--text);
  background-color: var(--accent);
  color: var(--text);
  cursor: pointer;
  box-shadow: 4px 4px 0 #000;
  transition: transform 0.05s, box-shadow 0.05s, background-color 0.15s;
  min-width: 120px;
}

button:hover {
  background-color: var(--primary);
  color: #fff;
}

button:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 4px;
}

button:active {
  transform: translate(4px, 4px);
  box-shadow: none;
}

.hint {
  margin-top: 24px;
  font-size: 0.875rem;
  opacity: 0.7;
}

@media (max-width: 400px) {
  .card {
    padding: 24px 16px;
  }
  .timer-display {
    font-size: 3rem;
  }
  button {
    font-size: 1rem;
    padding: 10px 16px;
    min-width: 100px;
  }
}

const WORK_TIME = 25 * 60;
const BREAK_TIME = 5 * 60;

const timerDisplay = document.getElementById('timer-display');
const modeIndicator = document.getElementById('mode-indicator');
const startPauseBtn = document.getElementById('start-pause');
const resetBtn = document.getElementById('reset');

let mode = 'work';
let remaining = WORK_TIME;
let running = false;
let intervalId = null;
let endTimestamp = 0;

function formatTime(seconds) {
  const m = Math.floor(seconds / 60).toString().padStart(2, '0');
  const s = (seconds % 60).toString().padStart(2, '0');
  return `${m}:${s}`;
}

function updateDisplay() {
  timerDisplay.textContent = formatTime(remaining);
  modeIndicator.textContent = mode === 'work' ? 'Work' : 'Break';
}

function switchMode() {
  mode = mode === 'work' ? 'break' : 'work';
  remaining = mode === 'work' ? WORK_TIME : BREAK_TIME;
  updateDisplay();
}

function tick() {
  const now = Date.now();
  const secondsLeft = Math.round((endTimestamp - now) / 1000);
  if (secondsLeft <= 0) {
    remaining = 0;
    updateDisplay();
    stopTimer();
    switchMode();
    return;
  }
  remaining = secondsLeft;
  updateDisplay();
}

function startTimer() {
  if (running) return;
  running = true;
  endTimestamp = Date.now() + remaining * 1000;
  intervalId = setInterval(tick, 1000);
  startPauseBtn.textContent = 'Pause';
  startPauseBtn.setAttribute('aria-label', 'Pause timer');
}

function stopTimer() {
  running = false;
  clearInterval(intervalId);
  intervalId = null;
  startPauseBtn.textContent = 'Start';
  startPauseBtn.setAttribute('aria-label', 'Start timer');
}

function resetTimer() {
  stopTimer();
  mode = 'work';
  remaining = WORK_TIME;
  updateDisplay();
}

function toggleTimer() {
  if (running) {
    stopTimer();
  } else {
    startTimer();
  }
}

startPauseBtn.addEventListener('click', toggleTimer);
resetBtn.addEventListener('click', resetTimer);

document.addEventListener('keydown', (e) => {
  if (e.target.tagName === 'BUTTON') return;
  if (e.code === 'Space') {
    e.preventDefault();
    toggleTimer();
  } else if (e.key === 'r' || e.key === 'R') {
    resetTimer();
  }
});

updateDisplay();
